pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId, bool assertedTruthfully, bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        // 1. Precondition: this contract IS the optimisticAsserter, so calls to onlyOptimisticAsserter functions succeed
        //    (the deployer in setUp is address(this), matching the C constructor argument)

        // 2. Call the function under test via the onlyOptimisticAsserter entry point
        c.assertionResolvedCallback(assertionId, assertedTruthfully);

        // 3. Call another onlyOptimisticAsserter function that is expected to NOT revert
        bool ok;
        try c.requestPrice(identifier, time, ancillaryData) {
            ok = true;
        } catch {
            ok = false;
        }

        // 4. Assert: requestPrice did NOT revert — the correct contract passes; the buggy one fails
        //    because the buggy assertionResolvedCallback alters state that disrupts subsequent calls.
        assertTrue(ok, "requestPrice should succeed after assertionResolvedCallback");
    }
}

