pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(bytes32 assertionId, bool assertedTruthfully) public {
        // 1. Assume the assertionId is valid, the assertion exists and belongs to c, and msg.sender is the optimisticAsserter
        vm.assume(address(c) != address(0));
        // The assertion must have been created; c is the callback recipient for this assertion (we set it back manually)
        // We need an assertion to exist, so we create one by calling assertTruth from the optimisticAsserter (this contract)
        bytes memory claim = bytes("");
        address asserter = address(0x1234);
        bytes32 id = c.assertTruthWithDefaults(claim, asserter);
        // Get the initial callback recipient before the call
        OptimisticAsserterInterface.Assertion memory assertionBefore = OptimisticAsserterInterface(address(this)).getAssertion(id);
        address callbackRecipientBefore = assertionBefore.callbackRecipient;
        // 2. Execute the callback as the optimisticAsserter
        c.assertionResolvedCallback(id, assertedTruthfully);
        // 3. Assert that the callback recipient remains unchanged
        OptimisticAsserterInterface.Assertion memory assertionAfter = OptimisticAsserterInterface(address(this)).getAssertion(id);
        assertEq(assertionAfter.callbackRecipient, callbackRecipientBefore);
    }

    // Mock the optimistic asserter interface to allow assertTruthWithDefaults and getAssertion
    function assertTruthWithDefaults(bytes memory, address) external returns (bytes32) {
        bytes32 assertionId = keccak256(abi.encodePacked(block.number, msg.sender));
        assertions[assertionId] = OptimisticAsserterInterface.Assertion({
            escalationManagerSettings: OptimisticAsserterInterface.EscalationManagerSettings({
                arbitrateViaEscalationManager: false,
                discardOracle: false,
                validateDisputers: false,
                assertingCaller: address(0),
                escalationManager: address(0)
            }),
            asserter: address(0x1234),
            assertionTime: uint64(block.timestamp),
            settled: false,
            currency: IERC20(address(0)),
            expirationTime: uint64(block.timestamp + 100),
            settlementResolution: false,
            domainId: bytes32(0),
            identifier: bytes32(0),
            bond: 0,
            callbackRecipient: address(c),
            disputer: address(0)
        });
        return assertionId;
    }

    function getAssertion(bytes32 assertionId) external view returns (OptimisticAsserterInterface.Assertion memory) {
        return assertions[assertionId];
    }

    mapping(bytes32 => OptimisticAsserterInterface.Assertion) private assertions;
}

