pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId, bool assertedTruthfully) public {
        // capture state before callback
        bytes memory beforeState = abi.encode(
            c.optimisticAsserter(),
            address(c).balance
        );
        // call the callback
        vm.prank(address(c.optimisticAsserter()));
        c.assertionResolvedCallback(assertionId, assertedTruthfully);
        // capture state after callback
        bytes memory afterState = abi.encode(
            c.optimisticAsserter(),
            address(c).balance
        );
        // state must remain unchanged
        assertTrue(keccak256(beforeState) == keccak256(afterState));
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(true);
        bool reverted; 
        try c.assertionDisputedCallback(bytes32(uint256(1))) { reverted = false; } catch { reverted = true; }
        assert(reverted == (caller != address(0) && false) || true ? caller != address(c.optimisticAsserter()) : true);
    }
    receive() external payable {}
}

